; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: ti83 (TI-83 Plus / 84 Plus (TI-OS)), starts in normal mode
; ============================================================

			org #9D95

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			di
			ld sp, ntc_ti_stack		; the platform's own real stack
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 21: Print "Files on "; System.Platform
			dw kw_printstrvar, str1
			dw kw_printnl

			; main.bas 22: Print "LOAD "; FileSystem.Capability("LOAD"); "  SAVE "; FileSystem.Capability("SAVE")
			dw kw_printstrvar, str4
			dw kw_printnl

			; main.bas 23: Print "SEQUENTIAL "; FileSystem.Capability("SEQUENTIAL"); "  RANDOMACCESS "; FileSystem.Capability("RANDOMACCESS")
			dw kw_printstrvar, str7
			dw kw_printnl

			; main.bas 24: Print "MAXOPEN "; FileSystem.Capability("MAXOPEN")
			dw kw_printstrvar, str9
			dw kw_printnl

			; main.bas 25: If FileSystem.Capability("DEVICES") Then Print "Devices "; FileSystem.Devices(); " - using "; FileSystem.CurrentDevice()
			dw if2_1_go
if1_1:

			; main.bas 26: If FileSystem.Capability("VOLUMES") Then Print "Volumes known "; FileSystem.Volumes(); " - using "; FileSystem.CurrentVolume()
			dw if2_1_go
if2_1:

			; main.bas 27: Print
			dw kw_printnl

			; main.bas 29: If FileSystem.Capability("SAVE") Then
			dw if3_1_go

			; main.bas 30: For i = 0 To 9 : hs(i) = 1000 - i * 50 : Next
for4_t:
			dw kw_mulvl, var_i, 50, tmp2
			dw kw_sublv, 1000, tmp2, tmp1
			dw kw_aset, arr_hs, var_i, tmp1
			dw kw_next1l_n, var_i, 9, for4_t
for4_e:

			; main.bas 31: r = FileSystem.Save("HISCORE.DAT", VarPtr(hs), 20)
			dw kw_ztov, var_r

			; main.bas 32: Print "Save HISCORE.DAT: "; r
			dw kw_printstrvar, str15
			dw kw_printint, var_r
			dw kw_printnl

			; main.bas 33: If FileSystem.Capability("LOAD") Then
			dw if6_1_go

			; main.bas 34: r = FileSystem.Load("HISCORE.DAT", VarPtr(back), 20)

			; main.bas 35: Print "Load: "; r; " bytes, "; back(0); " ... "; back(9)

			; main.bas 36: End If
if5_1:

			; main.bas 37: Else
			dw if6_1_go
if3_1:

			; main.bas 38: Print "No saving on this platform"
			dw kw_printstrvar, str19
			dw kw_printnl

			; main.bas 39: End If
if3_e:

			; main.bas 41: If FileSystem.Capability("SEQUENTIAL") Then
			dw if6_1_go

			; main.bas 42: h = FileSystem.Open("NOTES.TXT", FileSystem.ForWrite)

			; main.bas 43: r = FileSystem.WriteLine(h, "Written by NTC BASIC")

			; main.bas 44: r = FileSystem.WriteLine(h, "Line two")

			; main.bas 45: r = FileSystem.Close(h)

			; main.bas 46: Print "NOTES.TXT:"

			; main.bas 47: h = FileSystem.Open("NOTES.TXT", FileSystem.ForRead)

			; main.bas 48: Do While Not FileSystem.Eof(h)
do7_t:

			; main.bas 49: Print "> "; FileSystem.ReadLine(h)
			dw kw_printstrvar, str24
			dw kw_printnl

			; main.bas 50: Loop
			dw do7_t_go
do7_e:

			; main.bas 51: r = FileSystem.Close(h)
			dw kw_ztov, var_r

			; main.bas 52: End If
if6_1:

			; main.bas 54: End
			dw kw_printnl0
			dw kw_printstrvar, str25
			dw kw_waitkey
			dw kw_stop

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if2_1_go:			ld sp, if2_1
			jp ntc_xn
if3_1_go:			ld sp, if3_1
			jp ntc_xn
if6_1_go:			ld sp, if6_1
			jp ntc_xn
do7_t_go:			ld sp, do7_t
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_i:			dw 0
var_r:			dw 0
var_h:			dw 0
tmp0:			dw 0
tmp1:			dw 0
tmp2:			dw 0

; numbers passed by address (read only)
vp_arr_hs:			dw arr_hs
vp_arr_back:			dw arr_back

; ============================================================
; Strings
; ============================================================

str0:			db "TI83", 0
str1:			db "Files on TI83", 0
str2:			db "LOAD", 0
str3:			db "SAVE", 0
str4:			db "LOAD 0  SAVE 0", 0
str5:			db "SEQUENTIAL", 0
str6:			db "RANDOMACCESS", 0
str7:			db "SEQUENTIAL 0  RANDOMACCESS 0", 0
str8:			db "MAXOPEN", 0
str9:			db "MAXOPEN 0", 0
str10:			db "DEVICES", 0
str11:			db "Devices 0 - using 0", 0
str12:			db "VOLUMES", 0
str13:			db "Volumes known 0 - using 0", 0
str14:			db "HISCORE.DAT", 0
str15:			db "Save HISCORE.DAT: ", 0
str16:			db "Load: ", 0
str17:			db " bytes, ", 0
str18:			db " ... ", 0
str19:			db "No saving on this platform", 0
str20:			db "NOTES.TXT", 0
str21:			db "Written by NTC BASIC", 0
str22:			db "Line two", 0
str23:			db "NOTES.TXT:", 0
str24:			db "> 0", 0
str25:			db "Press a key", 0
str26:			db 0

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared ntc_d_nmode
; ------------------------------------------------------------
; Scratch space: the core every program has (with ntc_d_nmode). The rest of
; the run time's variables are @data sections, each linked only when a
; linked section's code names one of its labels (no header lists them).
; They stay in this order: the keyword ROM's registry keeps each variable's
; address (a Library: ROM program has them as fixed addresses)
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread

;## ntc_d_nmode @data
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)

;## ntc_d_lead @data
ntc_lead:		db 0			; printint: digit seen

;## ntc_d_sptr @data
ntc_sptr:		dw 0			; printbuf: text pointer

;## ntc_d_numbuf @data
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			ld ix, ntc_next
			jp ntc_plat_getkey

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			nop					; an interrupt can be taken here
			di
			ld sp, (ntc_ip)
			ret

;## ntc_for_jump (normal mode copy)
; tails for the FOR / NEXT keywords. DE = var value, HL = limit,
; SP = thread at the label word. Signed compare by flipping bit 15.
; ntc_for_gt: jump to the label if var > limit, else skip it
ntc_for_gt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, carry = var > limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_lt: jump to the label if var < limit, else skip it
ntc_for_lt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, carry = var < limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_le: jump to the label if var <= limit (loop again). A not 0: the
; step took var past 32767 (or -32768): the loop ends (ntc_for_ge too)
ntc_for_le_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, no carry = var <= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_ge: jump to the label if var >= limit (loop again)
ntc_for_ge_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, no carry = var >= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
ntc_for_end_n:
			pop hl
			jp ntc_xn

;## kw_next1l (normal mode copy) ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit
kw_next1l_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1l_nc_n
			inc (hl)
ntc_n1l_nc_n:
			ld d, (hl)
			pop hl
			ld a, d					; A = #FF when it went past 32767 (#8000)
			xor #80
			or e
			sub 1
			sbc a, a
			jp ntc_for_le_n

;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			xor a
			pop hl
			ld (hl), a
			inc hl
			ld (hl), a
			ret

;## kw_sublv
;kw_sublv, <literal>, <var>, <destvar>  - literal - var
kw_sublv:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ex de, hl
			or a
			sbc hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_mul
; BC * DE -> pop destvar, store. Low 16 bits (same signed/unsigned)
ntc_mul:
			ld hl, 0
			ld a, 16
ntc_mul_loop:
			add hl, hl
			sla e
			rl d
			jr nc, ntc_mul_skip
			add hl, bc
ntc_mul_skip:
			dec a
			jr nz, ntc_mul_loop
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_mulvl ntc_mul
;kw_mulvl, <var>, <literal>, <destvar>
kw_mulvl:
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			pop de
			jp ntc_mul

;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			ex de, hl
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			ex de, hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			ld a, (ntc_curx)
			or a
			ret z
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			jr z, ntc_bs_ok		; (the stack just under them: CP/M's ntc_cpmstack = their start)
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "GURU 001", 0

;## ntc_plat_data
; ------------------------------------------------------------
; TI-OS bcall equates - standard ti83plus.inc values.  ;!!TI confirm every one
; against your ti83plus.inc (the include can't be downloaded in this box).
; ------------------------------------------------------------
_PutC            equ #4504   ; A = char at cursor, advance curCol            ;!!TI
_PutS            equ #450A   ; HL = zero-terminated string                   ;!!TI
_NewLine         equ #452E   ; CR+LF, scroll if needed                       ;!!TI
_ClrLCDFull      equ #4540   ; clear the whole LCD                           ;!!TI
_HomeUp          equ #4558   ; curRow = curCol = 0                           ;!!TI
_GetCSC          equ #4018   ; A = scan code (0 = none), non-blocking        ;!!TI
_GetKey          equ #4972   ; A = key code, blocking (2nd/alpha handled)    ;!!TI
_JForceCmdNoChar equ #4027   ; clean return to the homescreen (exit)         ;!!TI
curRow           equ #844B   ; OS text cursor row  (0-7)                     ;!!TI
curCol           equ #844C   ; OS text cursor col  (0-15)                    ;!!TI

ntc_curx:		db 0			; column mirror (0 based) - counted for Tab
ntc_cury:		db 0			; row mirror (0 based)
ntc_scols:		db 16			; columns (large-font grid)                 ;!!TI
ntc_ti_stack	equ ntc_end + 256	; the real stack: the 256 bytes above the program image.
									; SP is swapped to it only for a bcall (which is shallow).

;## ntc_ti_call ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_ti_call - IY = a real-stack routine (it may bcall). SP is the thread;
; swap it to the real stack (ntc_csp), call the routine, swap back, keep IX.
; This is the MSX ntc_vcall pattern retargeted to TI-OS. Registers pass
; straight through to/from the routine (A = char for putc, A = key out, ...).
; ------------------------------------------------------------
ntc_ti_call:
			ld (ntc_tiix), ix
			ld (ntc_tisp), sp
			ld sp, (ntc_csp)
			call ntc_ti_call_jp
			ld sp, (ntc_tisp)
			ld ix, (ntc_tiix)
			jp (ix)
ntc_ti_call_jp:
			jp (iy)
ntc_tiix:		dw 0			; IX over the call
ntc_tisp:		dw 0			; the thread's SP over the call

;## ntc_plat_screen ntc_ti_call ntc_plat_data ntc_data
; ntc_plat_putc - A = character to the screen (_PutC), mirror curCol into ntc_curx
ntc_plat_putc:
			ld iy, ntc_tir_putc
			jp ntc_ti_call
ntc_tir_putc:
			rst #28
			dw _PutC				; A = char; OS advances/wraps curCol
			ld a, (curCol)
			ld (ntc_curx), a
			ret

; ntc_plat_newline - _NewLine, then curx mirror = 0
ntc_plat_newline:
			ld iy, ntc_tir_newline
			jp ntc_ti_call
ntc_tir_newline:
			rst #28
			dw _NewLine
			xor a
			ld (ntc_curx), a
			ret

;## ntc_plat_key ntc_ti_call ntc_data
; ntc_plat_scankey - A = key or 0 (non-blocking, _GetCSC).
; ;!!TI _GetCSC returns a TI SCAN CODE (skEnter, sk0..., skGraph), NOT ASCII.
; A scancode->ASCII map (below, stubbed) is needed before Inkey reads sanely.
ntc_plat_scankey:
			ld iy, ntc_tir_scan
			jp ntc_ti_call
ntc_tir_scan:
			rst #28
			dw _GetCSC				; A = scan code or 0
			; ;!!TI map A (scan code) -> ASCII here; raw code passed through for now
			ret

; ntc_plat_getkey - wait for a key (poll _GetCSC so interrupts aren't required)
ntc_plat_getkey:
			ld iy, ntc_tir_getk
			jp ntc_ti_call
ntc_tir_getk:
			rst #28
			dw _GetCSC
			or a
			jr z, ntc_tir_getk
			; ;!!TI map A (scan code) -> ASCII here too
			ret

;## ntc_plat_exit ntc_ti_call ntc_plat_data ntc_data
; ntc_plat_exit - clean return to the homescreen. SP is the mangled thread, so
; a plain ret can't go back; _JForceCmdNoChar resets the OS to the homescreen
; regardless of the stack. Swap to the real stack first.
ntc_plat_exit:
			ld sp, (ntc_csp)
			rst #28
			dw _JForceCmdNoChar		; does not return
			ret						; (unreached)                            ;!!TI

;## ntc_plat_memtop ntc_plat_data
; ntc_plat_memtop - HL = the first byte the Memory heap must not use (it grows
; down from here, as CP/M's heap grows down from #FFFF). ;!!TI #FB00 is a
; conservative ceiling below TI-OS high system RAM; confirm free RAM on the
; target OS version (saveSScreen / appBackUpScreen are also usable scratch).
ntc_plat_memtop:
			ld hl, #FB00
			ret


ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_hs		equ ntc_bss + 0		; 20 bytes
arr_back		equ ntc_bss + 20		; 20 bytes
ntc_bss_size	equ 40
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
